/* Throwaway, in-memory UX prototype. No application API calls or real broadcasts. */
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={live:'M3 5h18v12H3z M8 21h8 M12 17v4',setup:'M4 5h16 M4 12h16 M4 19h16 M8 3v4 M16 10v4 M10 17v4',library:'M3 5h7l2 3h9v12H3z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',arrow:'M5 18L19 4 M5 4h14v14',play:'M8 5l11 7-11 7z',music:'M9 18V5l11-2v13 M9 5l11-2 M4 18a3 2 0 1 0 6 0 3 2 0 1 0-6 0 M15 16a3 2 0 1 0 6 0 3 2 0 1 0-6 0',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',check:'M5 12l4 4L19 6',more:'M5 12h.01 M12 12h.01 M19 12h.01',close:'M6 6l12 12 M18 6L6 18',back:'M15 5l-7 7 7 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',pause:'M8 5v14 M16 5v14',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.library}"/></svg>`;
const art=t=>`assets/${t||'workshop'}.png`;
const names={pre:'Starting soon',brb:'BRB',end:'Ending'};
let serial=30, toastTimer, generationTimer, focusReturn;
const tracks=Array.from({length:14},(_,i)=>({id:'t'+i,name:['Solder & synths','Late-night build','A little more time','Machine dreams','Neon reflections','Quiet circuits','First layer','After the last print','Warm filament','Blueprints','Workbench radio','Small discoveries','Midnight loop','One last idea'][i],duration:['3:42','4:18','2:56','5:08','3:35','4:12'][i%6]}));
const playlists=[{id:'p0',name:'Workshop radio',tracks:['t0','t1','t2'],revision:1},{id:'p1',name:'After hours',tracks:['t4','t5','t6','t7'],revision:1},{id:'p2',name:'Arcade mix',tracks:['t3','t4','t8'],revision:1}];
const designs=[{id:'d0',name:'Workshop opening',stage:'pre',theme:'workshop',text:'THE WORKSHOP OPENS SOON',music:'p0',mode:'music',version:1},{id:'d1',name:'A little workshop break',stage:'brb',theme:'workshop',text:'BE RIGHT BACK',music:'p0',mode:'music',version:1},{id:'d2',name:'After-hours sign-off',stage:'end',theme:'neon',text:'THANKS FOR HANGING OUT',music:'p1',mode:'music',version:1},{id:'d3',name:'Arcade intermission',stage:'brb',theme:'pacman',text:'BE RIGHT BACK',music:'p2',mode:'music',version:1},{id:'d4',name:'Christmas workshop',stage:'pre',theme:'christmas',text:'A LITTLE FESTIVE MAKING',music:'p0',mode:'fixed',version:1},{id:'d5',name:'Friday experiments',stage:'pre',theme:'neon',text:'LET’S TRY SOMETHING NEW',music:'t3',mode:'music',version:1}];
let videos=designs.flatMap((d,i)=>[0,1].map((x)=>({...d,id:'v'+i+'-'+x,design:d.id,label:x?'Original music':'Updated music',when:x?'Oct 24 · 18:40':'Today · 10:24',music:x?'t0':d.music,draftVersion:1})));
const state={page:'setup',view:'designs',editor:'d1',inspector:'content',stage:'off',rehearsal:false,active:null,returnStage:null,returnVideo:null,selected:{pre:'v0-0',brb:'v1-0',end:'v2-0'},override:null,failure:null,job:null,checked:new Set(),filter:'',query:'',empty:false,stale:false,failNext:false,saveError:false,partialDelete:false,libraryMode:'tracks',selectedScene:0,returnTo:'setup',keyShown:false,settings:'ingestion',destinations:[{name:'Twitch',platform:'Twitch',enabled:true},{name:'YouTube',platform:'YouTube',enabled:true}],uploads:[{name:'Workshop logo.png',kind:'Image',uses:'Used in 2 designs'},{name:'Printer close-up.mp4',kind:'Video',uses:'Ready for clip playback'},{name:'New project reveal.mp4',kind:'Video',uses:'Used in 1 design'}]};
const getDesign=id=>designs.find(d=>d.id===id);
const getVideo=id=>videos.find(v=>v.id===id);
const musicName=id=>playlists.find(p=>p.id===id)?.name||tracks.find(t=>t.id===id)?.name||'No music';
const length=id=>{const p=playlists.find(p=>p.id===id); if(!p)return tracks.find(t=>t.id===id)?.duration||'0:30';let n=p.tracks.reduce((n,id)=>{const t=tracks.find(t=>t.id===id);const[a,b]=(t?.duration||'0:00').split(':').map(Number);return n+a*60+b},0);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`};
designs.forEach(d=>{d.musicLabel=musicName(d.music);d.musicDuration=length(d.music);d.musicRevision=playlists.find(p=>p.id===d.music)?.revision||1});
videos.forEach(v=>{v.musicLabel=musicName(v.music);v.musicDuration=length(v.music)});
const videoMusic=v=>v.musicLabel||musicName(v.music);
const videoLength=v=>v.musicDuration||length(v.music);
const behavior=v=>v.mode==='music'?'Loops until stopped':v.stage==='end'?'Stops broadcast when finished':'Loops until stopped';
const badge=(s,c='')=>`<span class="badge ${c}">${esc(s)}</span>`;
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function openDialog(title,body,footer=''){const d=$('#dialog');if(!d.open)focusReturn=document.activeElement;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn(icon('close'),'close','menu-button','aria-label="Close dialog"')}</div>${body}${footer?`<div class="dialog-footer">${footer}</div>`:''}`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();else d.querySelector('button')?.focus()}
function closeDialog(){const d=$('#dialog');d.querySelectorAll('video').forEach(v=>v.pause());d.close();if(focusReturn?.isConnected)focusReturn.focus();else $('#main')?.focus({preventScroll:true})}
function nav(page,view=''){state.query='';state.checked.clear();location.hash=page+(view?'/'+view:'');}
function route(){let[a,b]=location.hash.slice(1).split('/');state.page=['live','setup','library','settings','editor'].includes(a)?a:'live';if(state.page==='library')state.view=b||'designs';if(state.page==='settings')state.settings=b||'ingestion';if(state.page==='editor')state.editor=getDesign(b)?b:'d1';render();$('#main').focus({preventScroll:true})}
window.addEventListener('hashchange',route);
function thumb(v,action='',cls=''){return `<${action?'button':'div'} class="thumb ${cls}" ${action?`data-action="${action}" aria-label="Preview ${esc(v.name)}"`:''}><img src="${art(v.theme)}" alt="${esc(v.name)}"><span class="thumb-title">${esc(v.text)}</span>${action?`<span class="play"><span>${icon('play')}</span></span>`:''}</${action?'button':'div'}>`}
function monitor(v){return `<div class="monitor"><img src="${art(v.theme)}" alt="${esc(v.theme)} scene artwork"><span class="scene-title">${esc(v.text)}</span></div>`}
function header(title,description='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`}
function navigation(){return ['live','setup','library','settings'].map(p=>`<a class="nav-link" href="#${p}" ${state.page===p||state.page==='editor'&&p===(state.returnTo==='setup'?'setup':'library')?'aria-current="page"':''}>${icon(p)}<span>${{live:'Live',setup:'Show setup',library:'Library',settings:'Settings'}[p]}</span></a>`).join('')}
function render(){const focused=document.activeElement;let focusSelector=null,focusIndex=0,selection=null;if(focused&&$('#app').contains(focused)){for(const attr of ['data-change','data-input','data-action','href'])if(focused.hasAttribute(attr)){focusSelector='['+attr+'="'+CSS.escape(focused.getAttribute(attr))+'"]';focusIndex=[...document.querySelectorAll(focusSelector)].indexOf(focused);break}if(['TEXTAREA','INPUT'].includes(focused.tagName)&&typeof focused.selectionStart==='number')selection=[focused.selectionStart,focused.selectionEnd]}const on=state.stage!=='off',active=getVideo(state.active);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#live" class="brand">${icon('arrow')}restreamer</a><nav class="main-nav" aria-label="Main navigation">${navigation()}</nav><div class="sidebar-foot"><strong>Personal studio</strong>All systems local</div></aside><div class="workspace"><header class="topbar"><div class="status-strip"><span class="status-dot ${state.failure?'bad':on?'on':''}"></span><strong>${state.stale?'Connection lost':on?(state.rehearsal?'Rehearsing':'Broadcasting'):'Not broadcasting'}</strong><span class="divider"></span><span class="subtle source-text">${on?(state.failure?'Emergency / fallback':state.stage==='live'?'OBS input':names[state.stage]||'Clip'):'Your changes stay off air'}</span></div><div class="top-actions">${state.job?btn(state.job.status==='running'?'Generating video…':state.job.status==='failed'?'Generation failed':'Video ready','jobs','link'):''}${on?btn('Open Live','open-live','link'):badge('Prototype')}<span class="avatar" aria-hidden="true">D</span></div></header><main id="main" tabindex="-1">${state.stale?`<div class="notice error">Connection lost. Status may be out of date. ${btn('Reconnect','reconnect','small secondary')}</div>`:''}${state.failure&&state.page!=='live'?`<div class="notice error row between"><span>${state.failure==='emergency'?'BRB playback failed. Silent emergency screen is playing.':'Input unavailable. BRB is keeping the show on screen.'}</span><a href="#live">Open Live</a></div>`:''}${({setup:setup,live:live,library:library,settings:settings,editor:editor}[state.page])()}</main></div></div>`;document.title=`Restreamer · ${{setup:'Show setup',live:'Live',library:'Library',settings:'Settings',editor:'Design editor'}[state.page]} · Prototype`;if(focusSelector){const restored=document.querySelectorAll(focusSelector)[focusIndex];if(restored){restored.focus({preventScroll:true});if(selection&&restored.setSelectionRange)restored.setSelectionRange(...selection)}}}
function setup(){return header('Show setup','Choose what plays before, during a break, and after your show.',`<a class="link" href="#live">Open Live ${icon('arrow')}</a>`)+`<div class="stage-list">${Object.entries(names).map(([k,label])=>{const v=state.empty?null:getVideo(state.selected[k]);const a=state.stage===k||state.stage==='live'&&state.failure&&k==='brb'?getVideo(state.active):null;return `<section class="stage-row"><div class="stage-label">${label}<small>${{pre:'Before the show',brb:'During a break',end:'After the show'}[k]}</small></div>${v?`${thumb(v,'preview:'+v.id)}<div class="stage-details"><a class="design-link" href="#editor/${v.design}" data-return="setup">${esc(v.name)}</a><div class="metadata">${icon('music')}${esc(videoMusic(v))}</div><div class="metadata">${behavior(v)}</div>${badge('Ready','ready')}<span class="created"> · ${v.when}</span>${a&&(a.id!==v.id||state.failure==='emergency')?`<div class="now-note">Playing now: ${state.failure==='emergency'?'Silent emergency screen':esc(a.name)+' · '+esc(a.when)}<br>This choice is for next use.</div>`:''}</div>${btn('Change','choose:'+k,'secondary stage-action',state.stale?'disabled':'')}`:`<div class="thumb"></div><div><h3>No video selected</h3><p class="hint">Choose a ready video or create a design.</p></div>${btn('Choose video','choose:'+k,'primary stage-action')}`}</section>`}).join('')}</div><div class="setup-footer"><details><summary>When a source is unavailable · ${state.override?'different video':'use selected BRB'}</summary><div class="disclosure-body"><p>Your selected BRB also plays when OBS disconnects, a video fails, or a clip is paused. A silent emergency screen is kept separately for playback failures.</p><label class="check"><input type="checkbox" data-change="override" ${state.override?'checked':''}> Use a different video when a source is unavailable</label>${state.override?`<div class="row gap">${esc(getVideo(state.override)?.name||'No override selected')}${btn('Change','choose:fallback','secondary small')}</div>`:''}</div></details></div>`}
function library(){const view=['designs','music','uploads','themes'].includes(state.view)?state.view:'designs';const title={designs:'Designs',music:'Music',uploads:'Uploads',themes:'Themes'}[view];const action=view==='designs'?btn('New design','new-design','primary desktop-only'):view==='music'?btn(state.libraryMode==='tracks'?'Upload music':'New playlist',state.libraryMode==='tracks'?'upload:music':'playlist:new','primary desktop-only'):view==='uploads'?btn('Upload files','upload:media','primary desktop-only'):btn('Create theme','new-theme','primary desktop-only');return header('Library','Everything you create and reuse in your show.',action)+`<nav class="tabs" aria-label="Library views">${['designs','music','uploads','themes'].map(v=>`<a href="#library/${v}" ${view===v?'aria-current="page"':''}>${{designs:'Designs',music:'Music',uploads:'Uploads',themes:'Themes'}[v]}</a>`).join('')}</nav>${view==='themes'?themes():`<div class="toolbar"><label class="search">${icon('search')}<input data-input="search" placeholder="Search ${title.toLowerCase()}…" aria-label="Search ${title.toLowerCase()}" value="${esc(state.query)}"></label>${view==='music'?`<div class="filter" aria-label="Music type">${btn('Tracks','music-mode:tracks',state.libraryMode==='tracks'?'active':'')}${btn('Playlists','music-mode:playlists',state.libraryMode==='playlists'?'active':'')}</div>`:view==='designs'?btn('Templates','templates','link desktop-only'):''}</div><div id="library-results">${libraryResults(view)}</div>`}`}
function libraryResults(view=state.view){if(state.empty)return `<div class="empty"><h2>Your ${view} will appear here</h2><p>Add your first resource to start preparing the show.</p>${btn('Add '+(view==='designs'?'design':view==='music'?'music':'files'),view==='designs'?'new-design':'upload:'+view,'primary desktop-only')}</div>`;const q=state.query.toLowerCase();let items=view==='designs'?designs:view==='music'?(state.libraryMode==='tracks'?tracks:playlists):state.uploads;items=items.filter(i=>i.name.toLowerCase().includes(q));let selection=state.checked.size?`<div class="selection-bar"><span>${state.checked.size} selected</span><div class="row">${btn('Cancel selection','clear-selection','small')}${btn('Delete selected','delete-selected','small danger')}</div></div>`:'';return selection+`<div class="list ${view==='designs'?'design-list':''}">${items.map(i=>view==='designs'?`<div class="list-row"><input type="checkbox" aria-label="Select ${esc(i.name)}" data-change="select" value="${i.id}" ${state.checked.has(i.id)?'checked':''}><img class="mini" src="${art(i.theme)}" alt=""><div><a class="title" href="#editor/${i.id}" data-return="library/designs">${esc(i.name)}</a><small>${videos.filter(v=>v.design===i.id).length} videos · edited today</small></div><span class="type-col hint">${names[i.stage]}</span><span class="optional">${badge('Ready','ready')}</span>${btn(icon('more'),'design-menu:'+i.id,'menu-button','aria-label="Options for '+esc(i.name)+'"')}</div>`:view==='music'?`<div class="list-row">${btn(icon(i.tracks?'music':'play'),(i.tracks?'playlist:':'listen:')+i.id,'menu-button','aria-label="'+(i.tracks?'Edit ':'Listen to ')+esc(i.name)+'"')}<div><button class="link title" data-action="${i.tracks?'playlist:':'listen:'}${i.id}">${esc(i.name)}</button><small>${i.tracks?i.tracks.length+' tracks · saved playlist':'Uploaded music'}</small></div><span class="usage hint">${i.tracks?'Used in '+designs.filter(d=>d.music===i.id).length+' designs':i.id==='t0'?'Used in 2 playlists':'Available'}</span><span class="duration hint">${length(i.id)}</span>${btn(icon('more'),'music-menu:'+i.id,'menu-button','aria-label="Options for '+esc(i.name)+'"')}</div>`:`<div class="list-row">${icon(i.kind==='Image'?'library':'play')}<div><span class="title">${esc(i.name)}</span><small>${esc(i.uses)}</small></div><span class="usage hint">${i.kind}</span>${btn('Use','upload-use:'+esc(i.name),'link')}${btn(icon('more'),'upload-menu:'+esc(i.name),'menu-button','aria-label="Options for '+esc(i.name)+'"')}</div>`).join('')}</div>${items.length?`<p class="result-count">${items.length} ${view==='music'?(state.libraryMode==='tracks'?'tracks':'playlists'):view}</p>`:'<div class="empty"><h2>No matches</h2><p>Try a different name.</p></div>'}`}
function themes(){return `<div class="theme-list">${[{id:'workshop',name:'Maker workshop',desc:'A busy little workshop. Built for making.'},{id:'pacman',name:'Arcade rev 2',desc:'Pixel worlds and playful intermissions.'},{id:'neon',name:'Neon light v2',desc:'After-hours color with room to breathe.'},{id:'christmas',name:'Christmas workshop',desc:'A seasonal edition of your workshop.'}].map(t=>`<article class="theme-item"><img src="${art(t.id)}" alt="${t.name} artwork"><div class="row between"><h3>${t.name}</h3>${badge('Built in')}</div><p>${t.desc}</p><div class="row">${btn('Preview & OBS border','theme:'+t.id,'link')}${btn('Customize','theme-edit:'+t.id,'small secondary desktop-only')}</div></article>`).join('')}</div>`}
function editor(){const d=getDesign(state.editor)||designs[0];const ready=videos.find(v=>v.design===d.id);const changed=!ready||d.version!==ready.draftVersion;return `<div class="breadcrumb"><a href="#${state.returnTo}">${icon('back')} ${state.returnTo==='setup'?'Show setup':'Designs'}</a><span>/</span><span>${names[d.stage]} design</span></div><div class="page-head editor-head"><div><h1>${esc(d.name)}</h1><p id="save-state">${state.saveError?'Could not save — your changes are kept here':changed?'Saved · Changes not generated':'All changes saved'}</p></div><div class="row">${btn('Video history','history:'+d.id,'secondary')}${btn(state.job?.status==='running'?'Generating…':'Generate video','generate','primary',state.job?.status==='running'||state.saveError?'disabled':'')}</div></div>${state.saveError?`<div class="notice error">Saving failed. Keep this page open or save a copy. ${btn('Retry save','retry-save','small secondary')}${btn('Save a copy','duplicate:'+d.id,'small secondary')}</div>`:''}<div class="mobile-authoring">${monitor(d)}<p class="hint">Open this design on desktop to edit content, music or appearance. You can preview and choose its ready videos here.</p>${btn('View ready videos','history:'+d.id,'primary')}</div><div class="editor-grid"><aside class="scene-column"><h2>${d.stage==='brb'?'Your break':'Scenes'}</h2>${(d.stage==='brb'?['Animated break']:['Welcome','What we’re making','See you soon']).map((s,i)=>`<button class="scene-item ${state.selectedScene===i?'selected':''}" data-action="scene:${i}"><img src="${art(d.theme)}" alt=""><span>${s}</span><small>${d.stage==='brb'?'Continuous loop':i===0?'20 seconds':'15 seconds'}</small></button>`).join('')}${d.stage!=='brb'?btn('Add scene','add-scene','link scene-list-footer'):''}</aside><section><div id="editor-preview">${monitor(d)}</div><div class="monitor-caption"><span>Draft preview</span><span>1920 × 1080 · 30 fps</span></div><p class="preview-note">${icon('music')} ${esc(videoMusic(d))} · ${behavior(d)}</p><div class="editor-history"><div class="row between"><h2>Latest video</h2>${ready?btn('Preview','preview:'+ready.id,'link'):''}</div><p class="hint">${ready?`${ready.when} · ${esc(videoMusic(ready))}`:'No video generated yet.'}</p>${changed?badge('Changes not generated','warning'):badge('Matches this design','ready')}</div></section><aside class="inspector"><div class="tabs" role="tablist" aria-label="Design properties">${['content','appearance','music'].map(t=>`<button data-action="inspector:${t}" aria-selected="${state.inspector===t}" tabindex="${state.inspector===t?0:-1}" role="tab">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="inspector-fields" role="tabpanel" aria-label="${state.inspector} properties">${state.inspector==='content'?`<label class="field full">${d.stage==='brb'?'BRB message':'Scene title'}<textarea rows="3" maxlength="80" data-input="message">${esc(d.text)}</textarea><small>Your message appears in the scene’s sign.</small></label>${d.stage!=='brb'?`<label class="field">Scene duration<select data-change="scene-duration"><option>20 seconds</option><option>30 seconds</option><option>60 seconds</option></select></label><label class="field">Transition<select data-change="transition"><option>Crossfade</option><option>Cut</option></select></label>`:`<p class="hint full">The animation loops continuously. Its music is configured in Music.</p>`}<details class="full"><summary>Advanced content settings</summary><label class="field">Text alignment<select data-change="text-align"><option>Center</option><option>Left</option></select></label></details>`:state.inspector==='appearance'?`<label class="field full">Theme<select data-change="theme">${['workshop','pacman','neon','christmas'].map(t=>`<option value="${t}" ${t===d.theme?'selected':''}>${{workshop:'Maker workshop',pacman:'Arcade rev 2',neon:'Neon light v2',christmas:'Christmas workshop'}[t]}</option>`).join('')}</select></label><label class="field">Accent color<input type="color" value="${d.color||'#edb467'}" data-change="color"></label><p class="hint full">Changes apply to this design. Your selected video stays unchanged.</p>${btn('Preview theme & OBS border','theme:'+d.theme,'link full')}<details class="full"><summary>Shared theme updates</summary><p class="hint">This design uses the latest saved theme. Future updates are adopted explicitly.</p></details>`:`<label class="field full">Music<select data-change="music"><option value="none" ${d.music==='none'?'selected':''}>No music</option><optgroup label="Playlists">${playlists.map(p=>`<option value="${p.id}" ${d.music===p.id?'selected':''}>${esc(p.name)} · ${d.music===p.id?videoLength(d):length(p.id)}</option>`).join('')}</optgroup><optgroup label="Tracks">${tracks.map(t=>`<option value="${t.id}" ${d.music===t.id?'selected':''}>${esc(t.name)} · ${t.duration}</option>`).join('')}</optgroup></select></label>${playlists.some(p=>p.id===d.music&&p.revision>d.musicRevision)?`<div class="notice neutral full"><strong>Playlist update available</strong><p>Your draft keeps its saved track order until you adopt the update.</p>${btn('Use updated playlist','adopt-playlist','secondary small')}</div>`:''}<div class="row full" style="margin:-6px 0 22px">${btn('Create playlist','playlist:new-editor','link')}${btn('Upload track','upload:music-editor','link')}</div><label class="field full">Video length<select data-change="mode"><option value="music" ${d.mode==='music'?'selected':''}>Follow music · ${videoLength(d)}</option><option value="fixed" ${d.mode==='fixed'?'selected':''}>Use scene duration · 0:50</option></select><small>${behavior(d)}. Downloads contain one pass.</small></label><label class="field full">Music volume<input type="range" min="0" max="100" value="${d.volume??65}" data-change="volume"><small>${d.volume??65}%</small></label><details class="full"><summary>Fades & source audio</summary><label class="field">Fade in<select data-change="fade"><option>2 seconds</option><option>None</option><option>5 seconds</option></select></label><label class="check"><input type="checkbox" checked data-change="source-audio"> Keep audio from scene videos</label></details>`}</div></aside></div>`}
function live(){const on=state.stage!=='off',v=getVideo(state.active);return header('Live',on?(state.rehearsal?'Rehearsal · destination delivery is blocked':'Your outgoing broadcast'):'Ready when you are.',`<a class="link" href="#setup">Show setup ${icon('arrow')}</a>`)+`${state.failure?`<div class="notice error row between"><span><strong>${state.failure==='emergency'?'BRB playback failed':'OBS input unavailable'}</strong><br>${state.failure==='emergency'?'Silent emergency screen is playing. Your selected BRB could not play.':'Your selected fallback is playing while the input recovers.'}</span>${btn('Recover source','recover','secondary small')}</div>`:''}<div class="live-layout"><section class="live-monitor">${on?(state.failure==='emergency'?`<div class="off-monitor"><h2>BE RIGHT BACK</h2><p>Silent emergency screen</p></div>`:v?monitor(v):`<div class="off-monitor"><h2>The workshop is live</h2><p>Simulated OBS input · no real broadcast</p></div>`):`<div class="off-monitor">${icon('live')}<h2>Your broadcast is stopped</h2><p>Preview your setup in rehearsal before going live.</p><div class="row">${btn('Rehearse','start:rehearsal','secondary')}${btn('Start broadcast','start:broadcast','primary')}</div></div>`}<div class="monitor-caption"><span>${on?`${state.rehearsal?'Rehearsing':'Playing now'} · ${state.failure?'Fallback':names[state.stage]||state.stage==='live'&&'OBS input'||'Clip'}`:'Outgoing monitor'}</span><span>${state.failure==='emergency'?'Silent emergency screen':on&&v?esc(v.name):'Preview never changes delivery'}</span></div>${on?`<div class="stage-controls">${['pre','live','brb','end'].map(s=>btn(s==='live'?'Go live':names[s],'stage:'+s,'secondary '+(state.stage===s?'active':''),state.stale?'disabled':'')).join('')}${state.returnStage?btn('Return to '+(names[state.returnStage]||'Live'),'return','secondary'):''}${btn('Stop','stop','stop')}</div>${v?`<div class="row between gap"><span class="hint">${behavior(v)}</span>${btn('Replace current video','replace','link')}</div>`:''}`:`<div class="readiness"><h2>Ready to start</h2>${['Stage videos selected','2 destinations enabled','OBS input connected'].map(t=>`<div class="readiness-row">${icon('check')}${t}</div>`).join('')}<a class="link" href="#setup">Review show setup</a></div>`}<div class="clips"><div class="row between"><h2>Clips</h2>${btn('Browse videos','browse-clips','link')}</div><div class="clip-buttons">${videos.filter(v=>['v3-0','v4-0','v5-0'].includes(v.id)).map(v=>`<button data-action="clip:${v.id}"><img src="${art(v.theme)}" alt=""><span>${esc(v.name)}</span></button>`).join('')}</div></div></section><aside class="live-aside"><section><div class="row between"><h2>OBS input</h2>${badge(state.failure?'Unavailable':'Connected',state.failure?'error':'ready')}</div><div class="signal-preview">${state.failure?'Waiting for input':'Workshop camera · demo'}</div><p class="hint gap">1920 × 1080 · 30 fps</p></section><section><h2>Destinations</h2>${state.destinations.map((d,i)=>`<div class="destination"><div><strong>${esc(d.name)}</strong><small>${state.rehearsal?'Blocked during rehearsal':on&&d.enabled?'Sending · demo':d.enabled?'Enabled · not sending':'Disabled'}</small></div><input type="checkbox" aria-label="Enable ${esc(d.name)} delivery" data-change="delivery" value="${i}" ${d.enabled?'checked':''}></div>`).join('')}<a class="link hint" href="#settings/destinations">Manage destinations</a></section><details><summary>Diagnostics</summary><p class="hint">Synthetic state. No packets are sent. Delivery and public platform playback remain separate facts.</p></details></aside></div>`}
function settings(){const s=state.settings;return header('Settings','Connections and technical setup.')+`<nav class="tabs" aria-label="Settings views">${['ingestion','destinations','profile'].map(t=>`<a href="#settings/${t}" ${s===t?'aria-current="page"':''}>${{ingestion:'Ingestion',destinations:'Destinations',profile:'Streaming profile'}[t]}</a>`).join('')}</nav><p class="mobile-only notice neutral">Configuration requires desktop. Connection information is available here.</p><div class="settings-body">${s==='ingestion'?`<div class="setting-row"><div><h2>Connect OBS</h2><p>Use these connection details in your streaming software.</p><label class="field">Server URL<input readonly value="rtmp://studio.example/live" aria-label="Server URL"></label><label class="field">Stream key<div class="setting-value"><input readonly type="${state.keyShown?'text':'password'}" value="demo-key-not-a-real-credential" aria-label="Demo stream key">${btn(state.keyShown?'Hide':'Reveal','reveal-key','secondary desktop-only')}${btn('Copy','copy-key','secondary desktop-only')}</div></label></div></div><div class="setting-row"><div><h2>Regenerate stream key</h2><p>The old key will no longer work for new connections. An existing connection continues until it disconnects.</p></div>${btn('Regenerate key','rotate-key','secondary desktop-only')}</div>`:s==='destinations'?`<div class="row between"><h2>Your destinations</h2>${btn('Add destination','destination:new','primary desktop-only')}</div>${state.destinations.map((d,i)=>`<div class="setting-row"><div><h3>${esc(d.name)}</h3><p>${esc(d.platform)} · ${d.enabled?'Enabled':'Disabled'}</p>${badge(state.stage==='off'?'Not sending':state.rehearsal?'Blocked in rehearsal':'Simulated delivery')}</div><div class="actions desktop-only">${btn('Edit','destination:'+i,'secondary')}${btn('Remove','remove-destination:'+i,'danger')}</div></div>`).join('')}`:`<div class="setting-row"><div><h2>Streaming profile</h2><p>Changing the profile may require your videos to be generated again.</p>${state.stage!=='off'?'<div class="notice">Stop the broadcast or rehearsal before changing the profile.</div>':''}<div class="settings-form"><label class="field">Resolution<select ${state.stage!=='off'?'disabled':''}><option>1920 × 1080</option><option>1280 × 720</option></select></label><label class="field">Frame rate<select ${state.stage!=='off'?'disabled':''}><option>30 fps</option><option>25 fps</option></select></label>${btn('Save profile','save-profile','primary desktop-only',state.stage!=='off'?'disabled':'')}</div></div></div>`}</div>`}
let chooserStage='brb',chooserReplace=false,playlistDraft=null,playlistFromEditor=false;
function chooser(stage,replace=false){chooserStage=stage;chooserReplace=replace;const target=stage==='fallback'?'brb':stage;const selected=stage==='fallback'?state.override:state.selected[stage];const ds=designs.filter(d=>d.stage===target);openDialog(replace?'Replace current video':stage==='fallback'?'Choose source-unavailable video':`Choose ${names[stage]} video`,`<p>${replace?'Review the video before replacing what is playing now.':'Choose an exact ready video for next use. Your current broadcast stays unchanged.'}</p>${ds.map(d=>{const vs=videos.filter(v=>v.design===d.id);const first=vs[0];if(!first)return '';const row=v=>`<div class="chooser-row">${thumb(v,'preview-choice:'+v.id)}<div><h3>${esc(v.name)}</h3><p>${esc(videoMusic(v))} · ${videoLength(v)}</p><p>${v.when} · ${behavior(v)}</p>${v.id===selected?badge('Selected for next use','ready'):badge(v.label||'Ready')}</div><div class="actions">${btn(replace?'Review replacement':'Use this video','use:'+v.id,'primary small',state.stale?'disabled':'')}</div></div>`;return row(first)+(vs.length>1?`<details ${vs.some(v=>v.id===selected&&v.id!==first.id)?'open':''}><summary>Older videos · ${vs.length-1}</summary>${vs.slice(1).map(row).join('')}</details>`:'')}).join('')}`,btn('Cancel','close','secondary'));}
function preview(id,backToChooser=false,backToResult=false,backToHistory=false){const v=getVideo(id);if(!v)return;openDialog(v.name,`${v.theme==='pacman'?'<video src="assets/arcade-demo.mp4" controls playsinline loop></video>':`<div class="art-preview"><img src="${art(v.theme)}" alt="${esc(v.name)}"><span class="overlay-title">${esc(v.text)}</span></div>`}<div class="row between gap"><span>${icon('music')} ${esc(videoMusic(v))}</span>${badge(behavior(v))}</div><p class="gap">${v.when} · ${esc(v.label)}. ${v.theme==='pacman'?'Illustrative arcade video; soundtrack is not the selected music.':'Illustrative scene preview; video generation and soundtrack playback are simulated.'}</p><details><summary>Technical details</summary><p>Prototype reference ${esc(v.id)} · 1920 × 1080 · captured design ${v.draftVersion}. Real hashes stay here in the production interface.</p></details>`,btn(backToChooser?'Back to videos':backToResult?'Back to ready video':backToHistory?'Back to history':'Close',backToChooser?'back-chooser':backToResult?'jobs':backToHistory?'history:'+v.design:'close','secondary'))}
function useVideo(id){const v=getVideo(id);if(chooserReplace){openDialog('Replace what is playing?',`<p>Playing now: <strong>${esc(state.failure==='emergency'?'Silent emergency screen':getVideo(state.active)?.name||'No video')}</strong></p><p>Replace with: <strong>${esc(v.name)}</strong> · ${v.when} · ${esc(videoMusic(v))}</p><p>This changes the outgoing video now. Your saved next-use selection stays unchanged.</p>`,btn('Cancel','back-chooser','secondary')+btn('Replace now','replace-confirm:'+id,'primary'));return;}if(chooserStage==='fallback')state.override=id;else state.selected[chooserStage]=id;state.empty=false;closeDialog();nav('setup');render();toast('Selected for next use. Current playback is unchanged.');}
function generate(captured){const d=getDesign(state.editor);if(!d||state.job?.status==='running')return;const snapshot=captured||structuredClone(d);snapshot.musicLabel=snapshot.musicLabel||musicName(snapshot.music);snapshot.musicDuration=snapshot.musicDuration||length(snapshot.music);state.job={status:'running',design:d.id,snapshot};render();toast('Generating video. You can keep working.');clearTimeout(generationTimer);generationTimer=setTimeout(()=>{if(state.failNext){state.failNext=false;state.job.status='failed';toast('Generation failed. Your previous video is still ready.')}else{const v={...snapshot,id:'v'+serial++,design:d.id,draftVersion:snapshot.version,label:'Newly generated',when:'Just now'};videos.unshift(v);state.job={status:'ready',design:d.id,video:v.id};toast('Your video is ready to review.')}render()},2600)}
function jobs(){const j=state.job;if(!j)return;const v=getVideo(j.video);if(j.status==='ready'&&!v){state.job=null;closeDialog();render();toast('This generated video was deleted.');return}openDialog(j.status==='ready'?'Your video is ready':j.status==='failed'?'Generation failed':'Generating video',j.status==='ready'?`${thumb(v,'preview-result:'+v.id)}<h3 class="gap">${esc(v.name)}</h3><p>${esc(videoMusic(v))} · ${behavior(v)}</p><p>${getDesign(v.design)?.version!==v.draftVersion?'This result uses an earlier draft. Later edits are not included.':'This video contains your saved changes.'} Review before selecting it.</p>`:j.status==='failed'?`<p>The music could not be read. Your selected video has not changed.</p><p>Retry uses the same captured design. You can also return to the editor to make changes.</p>`:`<p>Preparing ${esc(j.snapshot.name)} with ${esc(musicName(j.snapshot.music))}.</p><progress aria-label="Generating video"></progress><p class="gap">You can leave this page. Selection and playback stay unchanged.</p>`,j.status==='ready'?btn('Keep for later','close','secondary')+btn('Use for '+names[v.stage],'use-generated:'+v.id,'primary'):j.status==='failed'?btn('Close','close','secondary')+btn('Retry generation','retry-generation','primary'):btn('Continue working','close','secondary'))}
function history(id){const d=getDesign(id);const vs=videos.filter(v=>v.design===id);openDialog('Videos · '+esc(d.name),`<p>Choose by preview, music and what changed. Selected and playing videos are protected.</p>${vs.map(v=>`<div class="history-row"><div><h3>${esc(v.label)}</h3><p>${v.when} · ${esc(videoMusic(v))}</p>${Object.values(state.selected).includes(v.id)?badge('Selected for next use','ready'):state.active===v.id?badge('Playing now','ready'):''}</div><div class="row">${btn('Preview','preview-history:'+v.id,'small secondary')}${btn('Use','history-use:'+v.id,'small primary')}${btn(icon('more'),'video-menu:'+v.id,'menu-button','aria-label="Video options '+v.id+'"')}</div></div>`).join('')}`,btn('Close','close','secondary'))}
function playlist(id,fromEditor=false){playlistFromEditor=fromEditor;const p=playlists.find(p=>p.id===id);playlistDraft=p?structuredClone(p):{id:null,name:'',tracks:['t0','t1']};playlistView()}
function playlistView(){const p=playlistDraft;openDialog(p.id?'Edit playlist':'New playlist',`<label class="field">Playlist name<input id="playlist-name" value="${esc(p.name)}" placeholder="e.g. Sunday workshop" maxlength="100"></label><h3>Playback order</h3><div>${p.tracks.map((id,i)=>{const t=tracks.find(t=>t.id===id);return `<div class="playlist-track"><span class="hint">${i+1}</span><div class="grow">${esc(t?.name)}<small>${t?.duration}</small></div>${btn('Up','track-up:'+i,'small secondary',i===0?'disabled':'')}${btn('Remove','track-remove:'+i,'small danger')}</div>`}).join('')||'<p>No tracks yet. Add music below.</p>'}</div><div class="row gap"><select id="track-add" aria-label="Choose track to add">${tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select>${btn('Add','track-add','secondary')}</div><p class="gap hint">Saved designs keep their selected playlist version until you choose the update.</p><p id="playlist-error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Save playlist','playlist-save','primary'))}
function newDesign(){openDialog('New design',`<label class="field">Name<input id="design-name" placeholder="e.g. Sunday workshop" maxlength="100"></label><label class="field">For<select id="design-stage"><option value="pre">Starting soon</option><option value="brb">BRB</option><option value="end">Ending</option></select></label><label class="field">Start from<select id="design-start"><option value="blank">Blank design</option><option value="template">Workshop template</option><option value="duplicate">Duplicate workshop opening</option></select></label><p id="form-error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Create design','create-design','primary'))}
function deletion(ids,type='design'){const selectedRefs=[...Object.values(state.selected),state.override,state.active,state.returnVideo];const entries=ids.map(id=>{const d=type==='design'?getDesign(id):getVideo(id);const refs=type==='design'?videos.filter(v=>v.design===id).map(v=>v.id):[id];return {id,name:d?.name||id,protected:refs.some(r=>selectedRefs.includes(r))||(type==='design'&&state.job?.status==='running'&&state.job.design===id),generating:type==='design'&&state.job?.status==='running'&&state.job.design===id,count:refs.length}});openDialog('Delete selected '+(type==='design'?'designs':'videos')+'?',`<p>Generated videos and their generated files will be deleted. Uploaded images, videos and music stay in your Library.</p>${entries.map(e=>`<div class="history-row"><div><h3>${esc(e.name)}</h3><p>${e.count} generated ${e.count===1?'video':'videos'}</p></div>${e.protected?badge(e.generating?'Protected · generating':'Protected · selected or playing','warning'):badge('Will be deleted')}</div>`).join('')}<p class="gap">Protected items will be kept. Change their assignment in Show setup, or wait for generation to finish first.</p>`,btn('Cancel','close','secondary')+btn('Delete '+entries.filter(e=>!e.protected).length+' unprotected','delete-confirm:'+type+':'+entries.filter(e=>!e.protected).map(e=>e.id).join(','),'danger secondary',entries.every(e=>e.protected)?'disabled':''))}
function destination(id){const d=state.destinations[Number(id)];openDialog(d?'Edit destination':'Add destination',`<label class="field">Platform<select id="platform" data-change="platform">${['Twitch','YouTube','Kick','Custom'].map(p=>`<option ${d?.platform===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="field">Name<input id="destination-name" value="${esc(d?.name||'Twitch')}" maxlength="100"></label><label class="field">Target URL<input id="destination-url" value="rtmp://live.twitch.tv/app"></label><label class="field">Stream key<input id="destination-key" type="password" placeholder="Demo only — do not enter a real key" autocomplete="off"></label><p>New destinations start disabled. This prototype never contacts a streaming platform.</p><p id="form-error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Save destination','destination-save:'+id,'primary'))}
function showLab(){const d=$('#lab');d.setAttribute('aria-labelledby','lab-title');d.innerHTML=`<div class="dialog-head"><h2 id="lab-title">Explore the prototype</h2>${btn(icon('close'),'lab-close','menu-button','aria-label="Close scenarios"')}</div><p>Synthetic data, real navigation. No broadcast, rendering or production changes occur. Reload resets everything.</p><div class="lab-state"><dl><dt>Mode</dt><dd>${state.stage==='off'?'Stopped':state.rehearsal?'Rehearsal':'Simulated broadcast'}</dd><dt>Playing</dt><dd>${state.failure==='emergency'?'Silent emergency screen':getVideo(state.active)?.name||state.stage}</dd><dt>BRB next use</dt><dd>${getVideo(state.selected.brb)?.name||'None'}</dd><dt>Generation</dt><dd>${state.job?.status||'Idle'}</dd></dl></div><div class="lab-options">${[['ready','Ready to prepare','Three scenes and a realistic music library.'],['onair','Already on air','Edit BRB; notice that playback stays pinned.'],['loss','OBS disconnects','The selected BRB takes over automatically.'],['emergency','BRB also fails','Independent silent screen and recovery.'],['fail','Generation fails','Next generation fails; retry keeps the old video.'],['empty','Empty Library','Explore first-use guidance and creation.'],['stale','Connection lost','Stale state and explicit reconnection.'],['save','Autosave fails','Retained draft and recovery.'],['cleanup','Cleanup with a partial failure','Select unused designs and delete.'],['reset','Reset demo','Restore the initial examples.']].map(([id,t,s])=>btn(`${t}<small>${s}</small>`,'scenario:'+id)).join('')}</div>`;if(!d.open)d.showModal();else d.querySelector('button')?.focus()}
function editChange(key,value){const d=getDesign(state.editor);d[key]=value;if(key==='music'){d.musicLabel=musicName(value);d.musicDuration=length(value);d.musicRevision=playlists.find(p=>p.id===value)?.revision||1}d.version++;}
function themeDialog(id){openDialog({workshop:'Maker workshop',neon:'Neon light v2',pacman:'Arcade rev 2',christmas:'Christmas workshop'}[id]||'Theme',`<div class="art-preview"><img src="${art(id)}" alt="Theme artwork"></div><p class="gap">Preview your theme and download the purpose-designed transparent border for OBS.</p><details><summary>OBS border · transparent center</summary><div class="border-preview"><img src="assets/workshop-border.png" alt="Maker workshop OBS border with transparent center"></div><p class="gap">Prototype includes the workshop border as a downloadable example.</p><a class="link" href="assets/workshop-border.png" download="workshop-obs-border.png">Download border PNG</a></details>`,btn('Close','close','secondary'))}
async function action(a){let [type,id,...rest]=a.split(':');if(matchMedia('(max-width:640px)').matches&&['playlist','new-design','create-design','generate','upload','design-menu','rename-music','delete-music','delete-selected','delete-design','theme-edit','new-theme','destination','rotate-key','save-profile','rename-video','delete-video'].includes(type)){openDialog('Continue on desktop','<p>Editing, generation and resource management are available on desktop. You can preview and select ready videos from Show setup on your phone.</p>',btn('Close','close','secondary'));return}switch(type){
case 'close':closeDialog();break;
case 'open-live':nav('live');break;
case 'reconnect':state.stale=false;render();toast('Connected. Status is current.');break;
case 'choose':chooser(id);break;
case 'back-chooser':chooser(chooserStage,chooserReplace);break;
case 'preview':preview(id);break;
case 'preview-result':preview(id,false,true);break;
case 'preview-history':preview(id,false,false,true);break;
case 'preview-choice':preview(id,true);break;
case 'use':useVideo(id);break;
case 'history-use':chooserStage=getVideo(id).stage;chooserReplace=false;useVideo(id);break;
case 'use-generated':chooserStage=getVideo(id).stage;chooserReplace=false;useVideo(id);break;
case 'inspector':state.inspector=id;render();document.querySelector('[role=tab][aria-selected=true]').focus();break;
case 'scene':state.selectedScene=Number(id);render();break;
case 'add-scene':openDialog('Add scene','<p>Choose the content for a new scene. This prototype demonstrates the shared editor; production retains every supported scene layout.</p><div class="lab-options">'+['Title','Text with image','List','Full-screen video'].map(s=>btn(s,'add-scene-choice:'+s,'secondary')).join('')+'</div>');break;
case 'add-scene-choice':closeDialog();toast(id+' scene added in the prototype.');editChange('version',getDesign(state.editor).version+1);render();break;
case 'generate':generate();break;
case 'adopt-playlist':editChange('music',getDesign(state.editor).music);render();toast('Updated playlist adopted in this draft. Existing videos stay unchanged.');break;
case 'jobs':jobs();break;
case 'retry-generation':{const j=state.job;state.editor=j.design;closeDialog();state.job=null;generate(j.snapshot);break;}
case 'history':history(id);break;
case 'playlist':playlist(id,id==='new-editor');break;
case 'track-add':playlistDraft.name=$('#playlist-name').value;playlistDraft.tracks.push($('#track-add').value);playlistView();break;
case 'track-up':playlistDraft.name=$('#playlist-name').value;[playlistDraft.tracks[id-1],playlistDraft.tracks[id]]=[playlistDraft.tracks[id],playlistDraft.tracks[id-1]];playlistView();break;
case 'track-remove':playlistDraft.name=$('#playlist-name').value;playlistDraft.tracks.splice(Number(id),1);playlistView();break;
case 'playlist-save':{const name=$('#playlist-name').value.trim();if(!name||!playlistDraft.tracks.length){$('#playlist-error').textContent='Add a name and at least one track.';return}playlistDraft.name=name;if(playlistDraft.id){const p=playlists.find(p=>p.id===playlistDraft.id);Object.assign(p,playlistDraft);p.revision++;}else{playlistDraft.id='p'+serial++;playlistDraft.revision=1;playlists.push(playlistDraft)}if(playlistFromEditor)editChange('music',playlistDraft.id);closeDialog();render();toast(playlistFromEditor?'Playlist saved and selected in this draft.':'Playlist saved. Existing videos stay unchanged.');break;}
case 'listen':{const t=tracks.find(t=>t.id===id)||playlists.find(p=>p.id===id);if(!t)return;openDialog(t.name,`<p>Duration ${length(t.id)}. This is a synthetic library entry; no real track is attached.</p><h3>Where it is used</h3>${playlists.filter(p=>p.tracks.includes(id)).map(p=>`<p>${esc(p.name)}</p>`).join('')||'<p>Not used in a playlist.</p>'}`,btn('Close','close','secondary'));break;}
case 'music-mode':state.libraryMode=id;state.query='';render();break;
case 'music-menu':openDialog('Music options',`<div class="lab-options">${btn('View uses','listen:'+id,'secondary')}${btn('Rename','rename-music:'+id,'secondary')}${btn('Delete','delete-music:'+id,'danger secondary')}</div>`);break;
case 'rename-music':{const t=tracks.find(t=>t.id===id)||playlists.find(p=>p.id===id);openDialog('Rename music',`<label class="field">Name<input id="rename-value" value="${esc(t.name)}"></label>`,btn('Cancel','close','secondary')+btn('Save name','rename-music-save:'+id,'primary'));break;}
case 'rename-music-save':{const t=tracks.find(t=>t.id===id)||playlists.find(p=>p.id===id);if(!$('#rename-value').value.trim())return;t.name=$('#rename-value').value.trim();closeDialog();render();break;}
case 'delete-music':openDialog('Music is protected','<p>Saved playlist versions and videos may still use this resource. The production flow lists each reference and allows deletion only when unused.</p>',btn('Close','close','secondary'));break;
case 'new-design':newDesign();break;
case 'create-design':{const name=$('#design-name').value.trim();if(!name){$('#form-error').textContent='Enter a design name.';return}const d={...designs[0],id:'d'+serial++,name,stage:$('#design-stage').value};designs.push(d);state.empty=false;closeDialog();state.returnTo='library/designs';nav('editor',d.id);break;}
case 'design-menu':openDialog(esc(getDesign(id).name),`<div class="lab-options">${btn('Rename','rename-design:'+id,'secondary')}${btn('Duplicate','duplicate:'+id,'secondary')}${btn('Video history','history:'+id,'secondary')}${btn('Save as template','save-template:'+id,'secondary')}${btn('Delete design','delete-design:'+id,'danger secondary')}</div>`);break;
case 'rename-design':openDialog('Rename design',`<label class="field">Name<input id="rename-value" value="${esc(getDesign(id).name)}"></label>`,btn('Cancel','close','secondary')+btn('Save name','rename-design-save:'+id,'primary'));break;
case 'rename-design-save':if(!$('#rename-value').value.trim())return;getDesign(id).name=$('#rename-value').value.trim();closeDialog();render();break;
case 'duplicate':{const d={...getDesign(id),id:'d'+serial++,name:getDesign(id).name+' copy'};designs.push(d);state.saveError=false;closeDialog();nav('editor',d.id);toast('Independent copy created.');break;}
case 'save-template':closeDialog();toast('Saved as a template. Existing designs are independent.');break;
case 'templates':openDialog('Templates','<p>Start a new independent design from reusable content.</p><div class="history-row"><div><h3>Workshop template</h3><p>Welcome, agenda and closing scenes</p></div>'+btn('Use template','new-design','primary')+'</div>',btn('Close','close','secondary'));break;
case 'delete-design':deletion([id]);break;
case 'delete-selected':deletion([...state.checked]);break;
case 'clear-selection':state.checked.clear();render();break;
case 'delete-confirm':{let ids=(rest[0]||'').split(',').filter(Boolean);let failed=state.partialDelete?ids.pop():null;state.partialDelete=false;ids.forEach(x=>{if(state.job&&(state.job.video===x||state.job.design===x))state.job=null;if(id==='design'){const i=designs.findIndex(d=>d.id===x);if(i>=0)designs.splice(i,1);videos=videos.filter(v=>v.design!==x)}else videos=videos.filter(v=>v.id!==x)});state.checked.clear();closeDialog();render();if(failed)openDialog('Some items could not be deleted',`<p>${ids.length} deleted. One simulated file cleanup failed. Uploaded files were kept.</p><p>Failed: ${esc(getDesign(failed)?.name||getVideo(failed)?.name)}</p>`,btn('Close','close','secondary')+btn('Retry deletion','delete-confirm:'+id+':'+failed,'primary'));else toast('Deleted generated content. Uploads were kept.');break;}
case 'video-menu':openDialog('Video options',`<div class="lab-options">${btn('Rename video','rename-video:'+id,'secondary')}${btn('Delete video','delete-video:'+id,'danger secondary')}</div>`);break;
case 'rename-video':openDialog('Name this video',`<label class="field">Friendly name<input id="rename-value" value="${esc(getVideo(id).label)}"></label>`,btn('Cancel','close','secondary')+btn('Save name','rename-video-save:'+id,'primary'));break;
case 'rename-video-save':getVideo(id).label=$('#rename-value').value.trim()||'Untitled video';closeDialog();history(getVideo(id).design);break;
case 'delete-video':deletion([id],'video');break;
case 'theme':themeDialog(id);break;
case 'theme-edit':openDialog('Customize theme',`<p>Save a separate style to reuse in your designs. Existing videos will stay unchanged.</p><label class="field">Name<input id="theme-name" value="My ${esc(id)} theme"></label><label class="field">Accent<input type="color" value="#edb467"></label>`,btn('Cancel','close','secondary')+btn('Save as new theme','save-theme','primary'));break;
case 'new-theme':action('theme-edit:workshop');break;
case 'save-theme':closeDialog();toast('Theme saved in this concept. Existing videos are unchanged.');break;
case 'upload':openDialog('Add '+(id.startsWith('music')?'music':'files'),`<p>Select a file to add a synthetic entry. File contents are not uploaded anywhere.</p><label class="field">Choose file<input id="upload-file" type="file" ${id.startsWith('music')?'accept="audio/*"':'accept="image/*,video/*"'}></label><p id="form-error" role="alert"></p>`,btn('Cancel','close','secondary')+btn('Add to Library','upload-confirm:'+id,'primary'));break;
case 'upload-confirm':{const f=$('#upload-file').files[0];if(!f){$('#form-error').textContent='Choose a file first.';return}if(id.startsWith('music')){const t={id:'t'+serial++,name:f.name,duration:'3:00'};tracks.push(t);if(id==='music-editor')editChange('music',t.id)}else state.uploads.push({name:f.name,kind:f.type.startsWith('image')?'Image':'Video',uses:'Unused'});state.empty=false;closeDialog();render();toast('Demo entry added. No file was uploaded.');break;}
case 'upload-use':openDialog('Use '+esc(id),`<div class="lab-options">${btn('Use in a design','new-design','secondary')}${id.endsWith('.mp4')?btn('Prepare for clip playback','prepare-upload','secondary'):''}</div>`);break;
case 'prepare-upload':closeDialog();toast('Prepared for playback in this simulation.');break;
case 'upload-menu':openDialog('Uploaded file',`<p>${esc(id)} is managed separately from designs. Deleting a design never deletes this file.</p><p>Production shows exact uses and protects referenced uploads.</p>`,btn('Close','close','secondary'));break;
case 'start':openDialog(id==='rehearsal'?'Start rehearsal':'Start broadcast',`<p>${id==='rehearsal'?'Preview your show with all destination delivery blocked.':'In the real app this sends your show to enabled destinations. This prototype only simulates it.'}</p><label class="field">Start with<select id="start-stage"><option value="pre">Starting soon</option><option value="live">OBS input</option><option value="brb">BRB</option></select></label>`,btn('Cancel','close','secondary')+btn(id==='rehearsal'?'Start rehearsal':'Start broadcast','start-confirm:'+id,'primary'));break;
case 'start-confirm':state.stage=$('#start-stage').value;state.rehearsal=id==='rehearsal';state.active=state.selected[state.stage]||null;state.failure=null;closeDialog();render();toast(state.rehearsal?'Rehearsal started. Delivery is blocked.':'Simulated broadcast started. Nothing is sent.');break;
case 'stage':state.stage=id;state.active=state.selected[id]||null;state.failure=null;render();break;
case 'stop':openDialog('Stop '+(state.rehearsal?'rehearsal':'broadcast')+'?',`<p>${state.rehearsal?'The rehearsal preview stops.':'This ends outgoing delivery immediately.'} Your videos and selections are kept.</p>`,btn('Keep playing','close','secondary')+btn('Stop now','stop-confirm','stop'));break;
case 'stop-confirm':state.stage='off';state.active=null;state.returnStage=null;state.returnVideo=null;state.failure=null;state.rehearsal=false;closeDialog();render();break;
case 'replace':if(state.stage==='clip')action('browse-clips');else chooser(state.stage==='live'?'fallback':state.stage,true);break;
case 'replace-confirm':state.active=id;state.failure=null;closeDialog();render();toast('Replaced current video. Next-use selection was kept.');break;
case 'recover':state.failure=null;state.stage='live';state.active=null;render();toast('Source recovered. OBS input is on air.');break;
case 'clip':if(state.stage==='off'){toast('Start a rehearsal or broadcast before playing a clip.');return}if(!state.returnStage){state.returnStage=state.stage;state.returnVideo=state.active}state.stage='clip';state.active=id;render();break;
case 'return':state.stage=state.returnStage||'live';state.active=state.returnVideo;state.returnStage=null;state.returnVideo=null;render();break;
case 'browse-clips':openDialog(state.stage==='clip'?'Replace current clip':'Choose a clip',`<p>Play a video, then return to the stage you interrupted.</p>${videos.filter(v=>v.id.endsWith('-0')).map(v=>`<div class="history-row"><span>${esc(v.name)}</span>${btn(state.stage==='clip'?'Replace clip':'Play clip','clip-dialog:'+v.id,'primary small')}</div>`).join('')}`,btn('Close','close','secondary'));break;
case 'clip-dialog':closeDialog();action('clip:'+id);break;
case 'reveal-key':state.keyShown=!state.keyShown;render();break;
case 'copy-key':try{await navigator.clipboard.writeText('demo-key-not-a-real-credential');toast('Demo key copied.')}catch{toast('Copy is unavailable here. Reveal the demo key to select it.')}break;
case 'rotate-key':openDialog('Regenerate stream key?','<p>Future connections need the new key. An existing connected publisher continues until it disconnects. Only a fake key is used in this prototype.</p>',btn('Cancel','close','secondary')+btn('Regenerate demo key','rotate-confirm','primary'));break;
case 'rotate-confirm':closeDialog();toast('Demo rotation complete. No real credentials changed.');break;
case 'destination':destination(id);break;
case 'destination-save':{const name=$('#destination-name').value.trim();if(!name){$('#form-error').textContent='Enter a name.';return}const d={name,platform:$('#platform').value,enabled:state.destinations[id]?.enabled||false};if(id==='new')state.destinations.push(d);else state.destinations[id]=d;closeDialog();render();toast('Demo destination saved. New destinations start disabled.');break;}
case 'remove-destination':openDialog('Remove '+esc(state.destinations[id].name)+'?',`<p>${state.stage==='off'?'Remove this destination from your configuration.':'This stops delivery to this destination. Other destinations keep running.'} Your local show can continue even with no destinations.</p>`,btn('Cancel','close','secondary')+btn('Remove destination','remove-destination-confirm:'+id,'danger secondary'));break;
case 'remove-destination-confirm':state.destinations.splice(Number(id),1);closeDialog();render();break;
case 'save-profile':openDialog('Update streaming profile?','<p>Existing videos may need preparation for the new profile. Uploaded files stay unchanged.</p>',btn('Cancel','close','secondary')+btn('Update profile','profile-confirm','primary'));break;
case 'profile-confirm':closeDialog();toast('Demo profile saved. Production would validate and prepare compatible media.');break;
case 'retry-save':state.saveError=false;render();toast('Draft saved.');break;
case 'lab-close':$('#lab').close();break;
case 'scenario':$('#lab').close();if(id==='reset'){location.reload();return}state.empty=false;state.stale=false;state.failure=null;state.saveError=false;state.stage='off';state.active=null;state.rehearsal=false;if(id==='ready')nav('setup');if(id==='onair'){state.stage='brb';state.active=state.selected.brb;nav('setup')}if(id==='loss'||id==='emergency'){state.stage='live';state.active=state.override||state.selected.brb;state.failure=id==='loss'?'input':'emergency';nav('live')}if(id==='fail'){state.failNext=true;nav('editor','d1');toast('Next generation will fail so you can try recovery.')}if(id==='empty'){state.empty=true;nav('library','designs')}if(id==='stale'){state.stale=true;nav('setup')}if(id==='save'){state.saveError=true;nav('editor','d1')}if(id==='cleanup'){state.partialDelete=true;nav('library','designs');toast('Select unused designs. The last deletion will fail once.')}render();break;
}}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const a=e.target.closest('[data-action]');if(a){e.preventDefault();action(a.dataset.action)}const link=e.target.closest('[data-return]');if(link)state.returnTo=link.dataset.return;});
document.addEventListener('change',e=>{const t=e.target,k=t.dataset.change;if(!k)return;switch(k){case 'select':t.checked?state.checked.add(t.value):state.checked.delete(t.value);$('#library-results').innerHTML=libraryResults();document.querySelector('[data-change=select][value="'+CSS.escape(t.value)+'"]')?.focus();break;case 'override':if(t.checked)chooser('fallback');else{state.override=null;render();toast('Next fallback uses the selected BRB. Current playback is unchanged.')}break;case 'theme':case 'music':case 'mode':editChange(k,t.value);render();break;case 'color':editChange(k,t.value);render();break;case 'volume':editChange(k,Number(t.value));render();break;case 'delivery':state.destinations[Number(t.value)].enabled=t.checked;render();break;case 'platform':$('#destination-name').value=t.value;$('#destination-url').value={Twitch:'rtmp://live.twitch.tv/app',YouTube:'rtmp://a.rtmp.youtube.com/live2',Kick:'rtmps://example.kick.invalid/app',Custom:''}[t.value];break;default:editChange(k,t.value||t.checked);toast('Draft saved. Generate a video to use these changes.')}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.input==='search'){state.query=t.value;$('#library-results').innerHTML=libraryResults()}if(t.dataset.input==='message'){editChange('text',t.value);$('#editor-preview .scene-title').textContent=t.value;$('#save-state').textContent=state.saveError?'Could not save — changes are kept here':'Saved · Changes not generated'}});
document.addEventListener('keydown',e=>{if(e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=['content','appearance','music'];state.inspector=tabs[(tabs.indexOf(state.inspector)+(e.key==='ArrowRight'?1:2))%3];render();document.querySelector('[role=tab][aria-selected=true]').focus()});
$('#lab-toggle').addEventListener('click',showLab);
$('#dialog').addEventListener('close',()=>{$('#dialog').querySelectorAll('video').forEach(v=>v.pause())});
route();
